window.SAQ_PAPER_QUESTIONS["2024-2-pah"]=[{"number":1,"title":"","stemText":"A 13 month old girl has been taken to the ED by the ambulance service. She was run over in her family’s driveway by a reversing car at low speed. On arrival her vital signs are: AVPU responds to pain Pulse 180 /min\n\nBP\n70/40 mmHg\n\nRR\n/min O2 sats 89% 15L via non-rebreather mask\n\nCap refill\nseconds Her chest x-ray is provided on the following page.","parts":[{"id":"p1","label":"Part 1","prompt":"State the 2 main pathologies present. Provide 2 supportive radiographic features for each. (6 marks) Pathology Supportive radiographic feature Her pelvic x-ray is provided below. 2. Interpret the pelvic x-ray. (1 mark) FAST scan is negative. You intend to perform intubation with simultaneous inter-costal catheter (ICC) insertion."},{"id":"p3","label":"Part 3","prompt":"State 3 potential difficulties that might be encountered. For each, provide a management\nstrategy. (6 marks) Potential difficulty Management strategy 4.\nList 5 safety steps in the performance of ICC insertion. Include the relevance of each.\n(5 marks)"}],"propPages":["asset:img026b7b24709d75733c","asset:imgf13605ff2d9a2a1e2a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Lung edge visible with radiolucent space to chest wall</td><td>Mediastinal shift to left</td></tr><tr><td>Bilateral lung contusions R&gt;L</td><td>Patchy opacification both lungs</td></tr><tr><td>Air bronchograms present right side</td><td>NOT accept haemothorax</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Normal pelvis xray</td><td>3.</td></tr><tr><td><strong>Worsening of tension physiology with PPV</strong> – ensure rapid decompression right chest, skilled</td><td>operator</td></tr><tr><td><strong>Severe hypoxia during induction</strong> – add 15L via NP to 15L BVM, bag through apnoea</td><td>Severe hypotension / arrest pot induction – pre-load with fluid, pre-treat with adrenaline boluses</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 75 year old man has presented with palpitations and shortness of breath.\nHis ECG is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the ECG. (4 marks) Your assessment reveals that the patient has pulmonary oedema."},{"id":"p2","label":"Part 2","prompt":"List 7 treatments you might use to manage this patient, including doses where\nappropriate. Provide the physiological justification for each treatment. (7 marks) Treatment Physiological justification"}],"propPages":["asset:imge1216d270b60d6779c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Atrial fibrillation – irregular rhythm</div><div class=\"answer-line\">Rapid ventricular response – rate approx. 150/min</div><div class=\"answer-line\">LBBB</div><div class=\"answer-line\">Broad QRS</div><div class=\"answer-line\">LAD</div><div class=\"answer-line\">LBBB pattern</div><div class=\"answer-line\">(VT critical error)</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Frusemide IV 40mg – decrease preload, improve cardiac contractility, decrease pulmonary oedema</td><td>Digoxin IV 500mcg – aim to decrease HR, provide minor increase cardiac contractility</td></tr><tr><td>IV MgSO4 10mmol – aim to decrease HR, improve ventricular filling / cardiac output</td><td>NIV / CPAP 10cmH20 – decrease preload, recruit alveoli, help oxygenation</td></tr><tr><td>Anti-coagulation eg clexane 1mg/kg – prevent atrial thrombus and embolism</td><td>GTN infusion – to decrease preload – improve cardiac output, also decrease afterload where</td></tr><tr><td>hypertension exists</td><td>Aspirin 300mg po – where ACS suspected, anti-platelet agent to prevent further coronary thrombus</td></tr><tr><td>formation</td><td>There will be others eg cardioversion</td></tr><tr><td>Eg</td><td>Abs to Rx infection precipitating</td></tr><tr><td>Inotropes</td><td>Not sure about beta-blockers in context of APO – probably C/I</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 3 year old boy has been brought to the ED with 2 days of rash to both lower limbs. The child is afebrile and alert.","parts":[{"id":"p1","label":"Part 1","prompt":"Describe the photo, including the most likely diagnosis. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 features of your history. Provide explanation for each. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 features of your examination. Provide explanation for each. (4 marks)"}],"propPages":["asset:img5a544eb272a869f059"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Well perfused lower limbs. Able to stand</div><div class=\"answer-line\">Purpuric rash symmetrical, widespread</div><div class=\"answer-line\">Some sparing flexural creases</div><div class=\"answer-line\"><strong>Henoch-Schonlein purpura </strong></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Presence of abdominal pain – makes HSP more likely, look for intussusception</td><td>Drug Hx eg new antibiotics – looking for drug reaction as cause</td></tr><tr><td>Testicular pain – looking for torsion complicating HSP</td><td>Recent URTI – often precedes HSP</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Vital signs – hypertension complicating renal involvement</td><td>Joints for polyarthritis</td></tr><tr><td>Abdo exam – looking for signs intussusception / bowel perf</td><td>Resp exam – can get alveolar haemorrhage with HSP</td></tr><tr><td>Neuro exam – can get encephalopathy with HSP</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 63 year old man has presented to the ED with severe abdominal pain of 4 hours duration.\nA slice from the CT scan of his abdomen is provided below. 1. Provide your clinical impression from this image, supported by 3 radiographic abnormalities. (4 marks) 2.","parts":[{"id":"p1","label":"Part 1","prompt":"List and justify 4 investigations you would perform. (4 marks)\nHis vital signs are:\n\nGCS\nE4 V4 M6 Pulse 130 /min\n\nBP\n85/60 mmHg O2 sats 99% 6L via Hudson mask\n\nRR\n/min 3."},{"id":"p2","label":"Part 2","prompt":"State 4 components of your management. (4 marks)"}],"propPages":["asset:imgb058ae110e3c6dc66e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Free air</div><div class=\"answer-line\">Free peritoneal fluid</div><div class=\"answer-line\">Thickened bowel wall</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">G+H – likely to require surgery, high chance blood loss</div><div class=\"answer-line\">VBG – define degree metabolic acidosis due to hypovolemia, raised lactate in bowel ischaemia</div><div class=\"answer-line\">Coag – exclude / correct coagulopathy prior to surgery in likely septic patient</div><div class=\"answer-line\">Renal function -define degree of AKI in hypovolemic pt, may alter Abs dose eg gentamicin</div><div class=\"answer-line\">ECG – exclude AF causing bowel ischaemia</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Analgesia – IV fentanyl 25mcg aliquots until pt comfortable</div><div class=\"answer-line\">IV fluid bolus 1L N/S aim systolc &gt;100mmHg</div><div class=\"answer-line\">IV Abs – eg pip/taz 4.5g</div><div class=\"answer-line\"><strong>Urgent surgical consult for laparotomy </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 25 year old woman presents with fever. She has non-Hodgkin lymphoma, is receiving chemotherapy and was neutropenic on blood tests taken yesterday.","parts":[{"id":"a","label":"Part A","prompt":"List four (4) antibiotics you might prescribe, including doses. For each, provide the clinical circumstance for its use and the microbiological spectrum covered. (12 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Pip-taz 4.5g – first line in febrile neutropenia – broad spectrum, gram pos and gram neg also</td><td>Pseudomonas</td></tr><tr><td>Tobramycin 7mg/kg – septic shock in addition to piptaz – better gram neg coverage</td><td>Vancomycin 30mg/kg load – indwelling line infection (also septic shock) – cover MRSA</td></tr><tr><td>Ceftazidime 2g – if minor penicillin allergy instead of pip/taz – broad spectrum gram pos and neg</td><td>also Pseudomonas</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 38 year old woman has presented to the ED with a headache. She is 38 weeks pregnant.\nYou are considering the diagnosis of pre-eclampsia. 1.","parts":[{"id":"p1","label":"Part 1","prompt":"List 4 risk factors for pre-eclampsia. (4 marks)\n2."},{"id":"p2","label":"Part 2","prompt":"List 4 examination features that would suggest pre-eclampsia. (4 marks)\n3."},{"id":"p3","label":"Part 3","prompt":"List and justify 5 investigations you would perform. (5 marks)\nHer initial vital signs were: Pulse /min\n\nBP\n180/100 mmHg\n\nRR\n/min O2 sats 98% room air Shortly after assessment, she begins to have a tonic clonic seizure. She has been taken to your resuscitation bay with ongoing seizures. 4."},{"id":"p4","label":"Part 4","prompt":"State 5 components of your management. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Prev Hx</div><div class=\"answer-line\">Fam Hx</div><div class=\"answer-line\">Inter-pregnancy interval &gt;10 yrs</div><div class=\"answer-line\">Nulliparity or multiple pregnancy</div><div class=\"answer-line\">Age&gt;40</div><div class=\"answer-line\">BMI &gt;30</div><div class=\"answer-line\">Maternal depression</div><div class=\"answer-line\">IVF</div><div class=\"answer-line\">Gestational trophoblastic diseae</div><div class=\"answer-line\">Medical conditions: congenital heart disease, DM, renal disease, hypertension, autoimmune</div><div class=\"answer-line\">disorders</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Hyper-reflexia</div><div class=\"answer-line\">Fetal growth restriction</div><div class=\"answer-line\">RUQ tenderness</div><div class=\"answer-line\">Confusion</div><div class=\"answer-line\">Peripheral oedema</div><div class=\"answer-line\">Crackles lungs</div><div class=\"answer-line\">Papilloedema</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Proteinuria – numbers not essential – confirm pre-eclampsia</div><div class=\"answer-line\">FBC – platelets low in HELLP, haemolysis in HELLP</div><div class=\"answer-line\">Creatinine – AKI</div><div class=\"answer-line\">Urate – elevated confirm Dx</div><div class=\"answer-line\">LFTs – raised LFTs HELLP</div><div class=\"answer-line\">Coags – for DIC</div><div class=\"answer-line\">CTG – for fetal wellbeing if &gt;28weeks</div></section><section class=\"answer-part\"><h5>Part 4</h5><div class=\"answer-line\">Left lateral to avoid IVC compression</div><div class=\"answer-line\">Terminate seizure – midazolam IV 5mg bolus</div><div class=\"answer-line\"><strong>MgSo4 – IV 20mmol slow push </strong></div><div class=\"answer-line\">Treat BP – eg hydralazine 5mg IV boluses aim BP &lt;140/90</div><div class=\"answer-line\"><strong>Urgent obstetric attendance to organise delivery </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 19 year old man has presented after an overdose of his mother’s metoprolol.\n1.\nState 3 clinical situations where decontamination with charcoal would be indicated.\n(3 marks) 2.","parts":[{"id":"p1","label":"Part 1","prompt":"List 8 treatment measures you might institute. Provide the indication for each. (8 marks)\nTreatment measure Indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Within 2 hours immediate release (and significant ingestion)</td><td>Within 4 hours SR (and significant ingestion)</td></tr><tr><td>Intubated with protected airway</td><td>2.</td></tr><tr><td>IV N/S 1L – first line hypotension</td><td>Atropine 1mg IV up to 3mg – initial therapy for bradycardia associated with hypotension</td></tr><tr><td>Adrenaline infusion – start 5mcg/min – for hypotension not responsive to IV fluids</td><td>Transcutaneous pacing – bradycardia not responsive to atropine and adrenaline</td></tr><tr><td>HIET – 1U/kg bolus then infusion, 50ml 50% dextrose – for myocardial depression on bedside echo</td><td>despite adrenaline (and ongoing hypotension)</td></tr><tr><td>Dextrose 5ml/kg 10% - to treat hypoglycaemia related to OD</td><td>Replace K to normal range – when using HIET</td></tr><tr><td>ECMO – for arrested patient if not responsive to other therapies</td><td>Intubate – for reduced level consciousness associated with shock</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 35 year old man has presented with fever, lethargy, dyspnoea and confusion.\nHe has no prior medical history. His full blood count is provided below.\n\nHb\ng/L (135 - 180) WBC 130.5 *10^9/L (4 - 11) plt *10^9/L (140 - 400) 1.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the blood results. (3 marks) 2."},{"id":"p2","label":"Part 2","prompt":"List 5 further investigations you would perform. Provide justification for each. (5 marks) Investigation Justification Shortly after commencement of a blood transfusion, the patient becomes more unwell. 3. List 4 types of adverse reactions to blood transfusion that could be causing this problem."},{"id":"p3","label":"Part 3","prompt":"For each, provide the discriminatory clinical features. (4 marks) Type of adverse reaction Clinical features"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Isolated raised wbc</div><div class=\"answer-line\">-</div><div class=\"answer-line\">With cytopenias other cell lines – anaemia, thrombosytopenia</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>CXR – for cause of SOB eg infection / leucostasis</td><td>G+H – likely to need a transfusion so can get Xmatched blood</td></tr><tr><td>VBG – assess degree of hypoperfusion from likely sepsis – metabolic acidosis / lactic acidosis</td><td>CT head – exclude spontaneous ICH in pt with severe thrombocytopenia</td></tr><tr><td>Renal function (urea / create) – look for AKI, adjust dosing meds eg aminoglycosides</td><td>ABG – assess degree of hypoxia from lung pathology</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Allergic – urticaria / wheezing / angio-oedema</td><td>TACO – dyspnoea, APO, hypertension, orthopnoea</td></tr><tr><td>Febrile non-haemolytic – fever, chills, headache – no other systemic signs</td><td>Haemolytic – fever, tachycardia, hypotension, chest/back pain</td></tr><tr><td>Others – bacterial infection / hypothermia</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 65 year old man has presented with weakness to both legs.\nYou are considering the diagnosis of Guillain-Barre syndrome (GBS). 1.\nList 4 differential diagnoses (apart from GBS) for this presentation. For each, state the","parts":[{"id":"p1","label":"Part 1","prompt":"discriminatory examination findings that would suggest its presence. (4 marks) Diagnosis Examination findings 2."},{"id":"p2","label":"Part 2","prompt":"State 2 typical features of GBS in each of history, examination and investigation. (6 marks) History Examination Investigation 3."},{"id":"p3","label":"Part 3","prompt":"State 2 life-threatening complications of GBS. (2 marks)\nPAH 2024.2 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Spinal cord compression – hyper-reflexia, hypertonia</div><div class=\"answer-line\">Cauda equina syndrome – loss peri-anal tone</div><div class=\"answer-line\">Tick paralysis – presence of tick on careful examination</div><div class=\"answer-line\">Myasthenia gravis – progressive fatigue with exercise</div><div class=\"answer-line\">Plenty of others – transverse myelitis</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Hx</td></tr><tr><td>-</td><td>recent diarrhea – Campylobacter</td></tr><tr><td>-</td><td>recent respiratory illness</td></tr><tr><td>-</td><td>ascending weakness</td></tr><tr><td colspan=\"2\">Ex</td></tr><tr><td>-</td><td>ascending LMN weakness</td></tr><tr><td>-</td><td>relative sensory sparing</td></tr><tr><td>-</td><td>areflexia</td></tr><tr><td colspan=\"2\">Ix</td></tr><tr><td>-</td><td>anti-ganglioside antibodies</td></tr><tr><td>-</td><td>CSF elevated protein / albuminocytological dissociation</td></tr><tr><td>-</td><td>Nerve conduction studies</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Autonomic instability</div><div class=\"answer-line\">Respiratory failure</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 26 year old man has been brought to the ED with a left knee injury following a rugby tackle. His x-ray is provided below. 1.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the x-ray, including radiographic supportive findings. (3 marks) 2.\nList 5 additional structures that might be injured. For each, provide the examination\nfindings consistent with its presence. (5 marks) Injured structure Examination findings 3."},{"id":"p2","label":"Part 2","prompt":"State 4 components of your management of this patient’s injury. (4 marks)"}],"propPages":["asset:img8c703a1a733d640f59"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Anterior displacement tibia and patella</td><td>No fracture</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>Popliteal artery</strong> – loss pop pulse / DP/PT</div><div class=\"answer-line\">Tibial nerve – loss foot plantar flexion</div><div class=\"answer-line\">Common peroneal nerve – loss foot dorsiflexion</div><div class=\"answer-line\">ACL – positive anterior drawer test</div><div class=\"answer-line\">PCL – posterior sag sign</div><div class=\"answer-line\">LCL/MCL – laxity on varus/valgus stretch</div><div class=\"answer-line\">3.</div><div class=\"answer-line\">Analgesia – IV morphine 2.5mg aliquots until comfortable</div><div class=\"answer-line\">Sedation / reduction</div><div class=\"answer-line\">Immobilisation</div><div class=\"answer-line\">Orthopaedic referral for definitive repair soft tissues</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 5 week old boy has been taken to the ED with projectile vomiting.\n1.\nState 5 differential diagnoses. For each, provide a key feature on history or examination\nthat would support its presence. (5 marks) Diagnosis History or examination feature A venous blood gas is provided below.\n\npH\n7.60 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (21 - 28)\n\nNa\n135 mmol/L (134 - 146)\n\nK\n3.1 mmol/L (3.4 - 5.0)\n\nCl\nmmol/L (98 - 108)\n\nGlucose\n2.6 mmol/L (3.6 - 8.0)","parts":[{"id":"p2","label":"Part 2","prompt":"State 4 abnormalities from the blood gas. Provide explanation for each. (4 marks)\nAbnormality Explanation"},{"id":"p3","label":"Part 3","prompt":"State 4 key components of your initial management. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Pyloric stenosis</strong> – palpable olive on abdo exam</td><td><strong>Sepsis</strong> – fever, poorly perfused, localising signs eg bulging fontanelle</td></tr><tr><td>Endocrine – eg CAH – genital findings eg pubic hair / ambiguous genitalia</td><td>NAI with ICH – bruising to head / signs BOS # / retinal haemorrhages</td></tr><tr><td>Surgical eg intussusception / herniae / malrotation – abdominal distension</td><td>Gastroenteritis - diarrhea</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\"><strong>Metabolic alkalosis</strong> – from vomiting – loss of acid</div><div class=\"answer-line\">Raised CO2 – appropriately raised – resp compensation</div><div class=\"answer-line\">Hypokalaemia – related to GI loss with vomiting, IC shift with alkalaemia</div><div class=\"answer-line\"><strong>Hypoglycaemia</strong> – due to lack of absorbed oral intake / vomiting</div><div class=\"answer-line\">Hypochloremia – loss HCl from vomiting</div><div class=\"answer-line\">3.</div><div class=\"answer-line\"><strong>Correct glucose – 5ml/kg 10%D </strong></div><div class=\"answer-line\">IV fluids – bolus NaCl 10ml/kg to correct hypoperfusion</div><div class=\"answer-line\">Surgical referral for correction pyloric stenosis</div><div class=\"answer-line\">Replace K – 20-40mmol/L in maintenance fluids 4:2:1 rule</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"An 8 year old indigenous girl has been brought to the ED with a two week history of fever, sore throat and lethargy. You are concerned about possible rheumatic fever.","parts":[{"id":"p1","label":"Part 1","prompt":"List 5 findings on examination that would suggest the diagnosis of rheumatic fever.\n(5 marks)"},{"id":"p2","label":"Part 2","prompt":"List 6 investigations you might perform, including justification for each. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Carditis eg regurgitant murmur</div><div class=\"answer-line\">Sydenham’s chorea</div><div class=\"answer-line\">Subcutaneous nodules</div><div class=\"answer-line\">Erythema marginatum</div><div class=\"answer-line\">Polyarthritis</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Throat swab to confirm Group A Strep</td><td>ASO / anti-DNA aseB on blood to confirm Strep</td></tr><tr><td>ESR/CRP – part of diagnostic confirmation rheumatic fever</td><td>Echocardiogram – delineate / exclude valve lesions from rheumatic fever</td></tr><tr><td>ECG – for prolonged PR – diagnostic rheumatic fever</td><td>CXR – define heart failure if carditis</td></tr><tr><td>BC – confirm Strep A – confirm sensitivities for long term AB therapy</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"You have been tasked to address the problem of prolonged delay to getting patients off ambulance stretchers (ambulance ramping) in your ED.","parts":[{"id":"p1","label":"Part 1","prompt":"State 4 adverse outcomes that are related to ambulance ramping. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 4 recommendations for improving ambulance ramping times. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 recommendations on the use of ambulance diversion. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Ambulance unable to provide community services</div><div class=\"answer-line\">Delayed access to timely ED services</div><div class=\"answer-line\">Financial implications for ambulance / hospitals</div><div class=\"answer-line\">Adverse publicity – staff morale / public perceptions</div><div class=\"answer-line\">Increase interpersonal conflict – patients / paramedics / ED / inpatient staff</div><div class=\"answer-line\">Increased out of area patients – cost of repatriation / assessment difficulties / complexity</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Planning to improve hospital flow</td></tr><tr><td>-</td><td>Discharge rounds</td></tr><tr><td>-</td><td>Discharge wards</td></tr><tr><td colspan=\"2\">More research required</td></tr><tr><td colspan=\"2\">Implement escalation procedures</td></tr><tr><td>-</td><td>Over-census beds on ward</td></tr><tr><td>-</td><td>Opening extra bed areas</td></tr><tr><td colspan=\"2\">Prohibit rapid offload – unsafe</td></tr><tr><td colspan=\"2\">Improve data collection</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Internal mechanisms to prevent diversion</div><div class=\"answer-line\">Activate internal disaster code</div><div class=\"answer-line\">Communication between hospital and ambulance</div><div class=\"answer-line\">Mutual decision making between hospital and ambulance</div><div class=\"answer-line\">Patient care to be prioritised</div><div class=\"answer-line\">Diversion not used to protect workflows</div><div class=\"answer-line\">High acuity patients not diverted</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 10 year old boy has presented with a limp.","parts":[{"id":"p1","label":"Part 1","prompt":"List 8 differential diagnoses. For each, provide a key finding on your assessment (history, examination or investigation). (8 marks) Diagnosis Key assessment finding On examination, the problem seems to be related to a painful hip joint."},{"id":"p2","label":"Part 2","prompt":"List 3 investigations you might perform. Provide justification for each. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Septic hip arthritis</strong> – fever, severely limited ROM hip</td><td>Transient synovitis – recent viral URTI,</td></tr><tr><td>Perthes disease – x-ray with AVN femoral head</td><td>SUFE – x-ray with slipped femoral head epiphysis</td></tr><tr><td># - Hx trauma, # on x-ray</td><td>Malignancy – FBC showing leukaemia, x-ray with bony tumour</td></tr><tr><td>Arthritis – red, hot, swollen joints – eg symmetrical polyarthritis</td><td>Abdominal pathology eg appendicitis – tender abdo examination</td></tr><tr><td>Others</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><strong>x-ray pelvis/hip</strong> – exclude Perthes / SUFE / #</td><td></td></tr><tr><td>USS hip – looking for effusion that can be subsequently drained for Dx / management</td><td></td></tr><tr><td>-</td><td>Joint fluid aspirate - WBC</td></tr><tr><td>Infective markers blood – WBC / ESR / CRP – part of Kocher’s criteria to Dx septic hip</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 55 year old woman has presented with a painful left eye.\nA clinical photograph is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"State the most likely diagnosis, with 3 supportive findings from the photograph. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"State 3 features of your assessment. Explain the significance of each. (3 marks)"},{"id":"p3","label":"Part 3","prompt":"State 4 treatments you might use for this patient. Provide justification for each. (4 marks)"}],"propPages":["asset:img6ef785251cade6e7f2"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Scleral injection</td></tr><tr><td>-</td><td>Hypopyon</td></tr><tr><td>-</td><td>Irregular pupil</td></tr><tr><td>-</td><td>Cloudy cornea</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\"><strong>VA</strong> – define sight threatening issue – use to allow comparison for deterioration</div><div class=\"answer-line\">Pupil light response – lack of constriction if synechiae</div><div class=\"answer-line\">IOP – glaucoma complicating iritis – sight threatening complication</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Analgesia – eg endone 5mg oral</td><td>Topical steroids – Rx iritis</td></tr><tr><td>Cycloplegic drops eg cyclopentolate – break synechiae</td><td>IOP lowering drops – eg B-blockers – prevent secondary glaucoma</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"An 82 year old woman has been found on the floor at home, following a fall 24 hours prior. Her initial venous blood gas is provided below:\n\npH\n7.21 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (21 - 28)\n\nNa\n140 mmol/L (134 - 146)\n\nK\n8.6 mmol/L (3.4 - 5.0)\n\nCl\n104 mmol/L (98 - 108)\n\nGlucose\n48.2 mmol/L (3.4 - 7.8)\n\nUrea\n40.3 mmol/L (2.1 - 7.1) Creat 324 umol/L (46 - 90)","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the acid-base abnormalities in the results provided. Provide formulae for your calculations. Provide the likely cause/s for each. (6 marks) Acid-base abnormality Formula Cause/s"},{"id":"p2","label":"Part 2","prompt":"State four other abnormalities. Explain the likely cause of each abnormality. (4 marks) Abnormality Cause Further assessment reveals no injuries from the fall. You think a urinary tract infection has been the cause of the fall.\nHer vital signs are:\n\nGCS\nE4 V4 M6 Pulse 115 /min\n\nBP\n85/40 mmHg\n\nRR\n/min O2 sats 98% room air Temperature 34.8 degrees Celsius"},{"id":"p3","label":"Part 3","prompt":"State 7 management components that you might employ. Provide justification for each.\n(7 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Na – (HCO3 + Cl)</td><td>= 21</td></tr><tr><td>Renal failure, potentially lactic acidosis, ketones ?DKA vs HHS</td><td>Low CO2</td></tr><tr><td>Respiratory compensation</td><td>1.5 * HCO3 +8</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Hyperglycaemia – DKA vs HHS, causes – sepsis/lack insulin</div><div class=\"answer-line\">Corrected Na – 155 – likely related to dehydration / lack oral intake</div><div class=\"answer-line\"><strong>Severe hyperK</strong> – corrected for pH – approx. 8.0 – renal failure/rhabdo</div><div class=\"answer-line\">Pre-renal renal failure – ratio &gt;100 – dehydration / sepsis causing hypovolemia</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>IV N/S 1L bolus</strong> – aim systolic &gt;100 – hypovolemia</td><td><strong>IV pip/taz 4.5g</strong> – Rx UTI/septic shock</td></tr><tr><td><strong>Ca gluconate 30mL 10%</strong> - cardiac membrane stabilisation for hyperK</td><td>IV HCO3 50mmol – reduce K with IC shift</td></tr><tr><td><strong>Insulin </strong>10U IV – reduce K</td><td>IV insulin infusion 0.1U/kg – manage DKA/HHS – reduce glucose</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 48 year old man has presented with abnormal behaviour.\nHe has a history of bipolar affective disorder and HIV.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 assessment features that would be consistent with mania. (6 marks)\nOn assessment, his presentation is more consistent with delirium.\nHis vital signs are:\n\nGCS\nE4 V4 M6\n\nHR\n/min\n\nBP\n110/50 mmHg\n\nRR\n/min\n\nTemp\n37.6 degrees"},{"id":"p2","label":"Part 2","prompt":"State 6 investigations you would perform. Provide the rationale for each. (6 marks)\nYour resident has sustained a needlestick injury while attempting IV access."},{"id":"p3","label":"Part 3","prompt":"State 6 factors that might influence the risk of HIV transmission to your resident.\n(6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Pressured speech</div><div class=\"answer-line\">Elevated mood</div><div class=\"answer-line\">Flight of ideas</div><div class=\"answer-line\">Psychomotor agitation</div><div class=\"answer-line\">Sexual disinhibition</div><div class=\"answer-line\">Hx spending money</div><div class=\"answer-line\">No sleep</div><div class=\"answer-line\">Grandiosity</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><strong>CD4+ count / viral load</strong> – assess for likelihood of AIDS defining illness</td><td><strong>CT head</strong> – exclude CNS masses – toxoplasmosis / lymphoma</td></tr><tr><td>CSF – exclude meningitis / encephalitis as cause of delirium</td><td>CXR – looking for pneumonia / Pneumocystis</td></tr><tr><td>TFTs – hyperthyroidism could cause presentation</td><td>FBC – plt count prior to performing LP</td></tr><tr><td>There will be others</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Pt viral load</div><div class=\"answer-line\">Pt treatment compliance to ARVT</div><div class=\"answer-line\">Doctor wearing gloves</div><div class=\"answer-line\">Blood contamination of needle</div><div class=\"answer-line\">Immediate first aid – washing wound</div><div class=\"answer-line\">Time to starting PEP</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 63 year old woman has presented with abdominal pain.\nShe has a history of type 2 diabetes mellitus complicated by end-stage renal failure. She undergoes daily peritoneal dialysis (PD). You are concerned that she has PD peritonitis.","parts":[{"id":"p1","label":"Part 1","prompt":"State 5 features from your history or examination that would be consistent with PD\nperitonitis. (5 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 intra-peritoneal antibiotics you might use. Include the intended microbiological\ncoverage. (3 marks) Shortly after treatment has commenced, the patient has requested to leave. You have been called to the patient’s bedside to manage the situation."},{"id":"p3","label":"Part 3","prompt":"State 4 components of your management of this situation. (4 marks)\nPAH 2024.2 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Cloudy PD fluid</div><div class=\"answer-line\">Hx of no-sterile contamination during change of bags</div><div class=\"answer-line\">Gradual onset generalised pain</div><div class=\"answer-line\">Generalised peritonism (not focal) on examination</div><div class=\"answer-line\">Inflamed Tenckhoff site</div><div class=\"answer-line\">Fever</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Cephazolin – cover gram positives eg Staph aureus</div><div class=\"answer-line\">Gentamicin – cover gram negatives eg E coli</div><div class=\"answer-line\">Vancomycin – for MRSA known or septic shock</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Find reason for leaving – can this be addressed? eg analgesia</div><div class=\"answer-line\">Arrange alternate Rx</div><div class=\"answer-line\">Arrange alternate follow up</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 68 year old female has presented after a fall onto her left wrist. She has no other injuries. Her x-rays are provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the x-ray. (3 marks) The patient has a history of severe aortic stenosis. You are considering the risks and benefits of procedural sedation."},{"id":"p2","label":"Part 2","prompt":"State 3 physiological principles in managing this patient’s cardiovascular status during a procedural sedation. For each, state your management to achieve your desired outcome. (6 marks) Physiological principle Management Given the high anaesthetic risk, the decision was made to perform a Bier’s block for closed reduction. Shortly after beginning the procedure, the patient became agitated and ripped off the Bier’s block cuff. She rapidly became unconscious with no palpable pulse. Her rhythm is PEA (pulseless electrical activity)."},{"id":"p3","label":"Part 3","prompt":"State 8 components of your management. (8 marks)"}],"propPages":["asset:imgfa60222147e148ed98"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Transverse distal radius fracture with volar angulation</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Risk / issue</th><th>Mitigation / management</th></tr></thead><tbody><tr><td>Avoid drop in pre-load – Ensure euvolaemia, low-dose sedation, most cardiac stable agent</td><td>Avoid drop in afterload - Avoid vasodilatory agents e.g. propofol, have vasopressor running</td></tr><tr><td>Avoid tachycardia - Avoid ketamine and pain</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Re-attach and inflate cuff up 100mmHg above systolic</td></tr><tr><td>-</td><td><strong>CPR 30:2 with 100% O2 via BVM until definitive airway at 120/min </strong></td></tr><tr><td>-</td><td><strong>100mmol bicarb push IV – aim pH 7.5 </strong></td></tr><tr><td>-</td><td>Consider Intralipid 1mL/kg every 3 min x 3 then infusion (source)</td></tr><tr><td>-</td><td>Early intubation to prevent acidosis/hypercarbia</td></tr><tr><td>-</td><td><strong>Adrenaline 1mg IV push immediately then every 2</strong><strong>nd</strong><strong> cycle as per ALS algorithm </strong></td></tr><tr><td>-</td><td>Early vasopressor given aortic stenosis (NA, vasopressin, phenylephrine, metaraminol with</td></tr><tr><td colspan=\"2\">dosing)</td></tr><tr><td>-</td><td>1L saline IV stat</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 45 year old male has presented with neck pain after a motor vehicle accident. He has no midline tenderness on examination. You intend to assess whether the C-spine can be cleared of injury with clinical assessment only.","parts":[{"id":"p1","label":"Part 1","prompt":"State the other low-risk factors as per the NEXUS criteria that would need to be satisfied for this to occur. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"List the defined dangerous mechanisms in the Canadian C-spine Rules (CCR). (5 marks)"},{"id":"p3","label":"Part 3","prompt":"List 3 exclusion criteria for a “simple rear-end MVA” as per the CCR. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">No focal neurological deficit</div><div class=\"answer-line\">Normal level of alertness</div><div class=\"answer-line\">Not intoxicated</div><div class=\"answer-line\">No painful distracting injury</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Fall &gt;3ft/5 stairs</div><div class=\"answer-line\">Axial load to head</div><div class=\"answer-line\">MVA at high speed (&gt;100km/hr), rollover or ejection</div><div class=\"answer-line\">Motorised recreational vehicle</div><div class=\"answer-line\">Bicycle struck or collision</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Pushed into oncoming traffic</div><div class=\"answer-line\">Hit by bus or large truck</div><div class=\"answer-line\">Rollover</div><div class=\"answer-line\">Hit by high speed vehicle</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 3 year old boy has been brought to the ED with prolonged and ongoing seizure activity. He had been found locked in the back seat of a car during a very hot day. Your assessment is consistent with status epilepticus due to heat stroke.\nHis vital signs are:\nTemperature 42.0 degrees Celsius Pulse 160 /min\n\nBP\n80/40 mmHg\n\nRR\n/min O2 sats 99% 15L O2 via non-rebreather mask","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 components of your initial management. (6 marks)"},{"id":"p2","label":"Part 2","prompt":"List 6 potential complications of this presentation. State how you will determine whether\neach complication is present. (6 marks) Given the clinical scenario, you are concerned about neglect."},{"id":"p3","label":"Part 3","prompt":"List 5 other physical signs of neglect you could look for when examining the child.\n(5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Keppra load 60mg/kg IV push</div><div class=\"answer-line\">IV N/saline 4 degrees IV 20mL/kg stat</div><div class=\"answer-line\">Ice packs to groin/axillae targeting temp 38-39 to prevent afterdrop</div><div class=\"answer-line\">Remove all clothing</div><div class=\"answer-line\">Fine mist of tepid air with warm forced fanning</div><div class=\"answer-line\">Early intubation via RSI and ongoing paralysis/sedation</div><div class=\"answer-line\"><strong>Some cooling essential </strong></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Rhabdomyolysis - CK</div><div class=\"answer-line\">Hypoglycaemia - BSL</div><div class=\"answer-line\">DIC – Coags</div><div class=\"answer-line\">AKI – Chem20</div><div class=\"answer-line\">Hypoxic ischaemic encephalopathy – CT brain with loss of grey white differentiation</div><div class=\"answer-line\">Ischaemic cardiomyopathy – Bedside echo showing poor LV contractility / Tn</div><div class=\"answer-line\">Aspiration pneumonia – CXR showing consolidation/pneumonitis</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Low body weight</td></tr><tr><td>-</td><td>Poor hygiene</td></tr><tr><td>-</td><td>Poorly kept clothing</td></tr><tr><td>-</td><td>Poor dentition</td></tr><tr><td>-</td><td>Low muscle mass</td></tr><tr><td>-</td><td>Bed sores</td></tr><tr><td>-</td><td>Severe nappy rash</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"An 8 day old boy has presented with fevers and frequent vomiting.\nHe was born at term with no complications.","parts":[{"id":"p1","label":"Part 1","prompt":"State 6 features of your examination. Provide justification for each. (6 marks)"},{"id":"p2","label":"Part 2","prompt":"List 6 investigations you might perform. Provide justification for each. (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Non-blanching petechiae - Serious bacterial infection / meningococcaemia</td><td>Distended abdomen - Malrotation with volvulus</td></tr><tr><td>Palpable hernia – Incarcerated hernia</td><td>Blood in bowel motion - NEC</td></tr><tr><td>Pallor during episodes – Intussusception</td><td>Bulging fontanelle – Raised ICP concerning for meningoencephalitis</td></tr><tr><td>Palpable olive – Pyloric stenosis</td><td><strong>Vital signs HR/BP – Bradycardia</strong> – Periarrest or tachycardia concerning for shock state</td></tr><tr><td>RR – Tachypnoea secondary to profound acidosis or pneumonia</td><td>SpO2 – Hypoxia secondary to pneumonia</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>FBC – Raised WCC consistent with sepsis</td><td>CRP – Elevated inflammatory markers non-specific (but in guideline)</td></tr><tr><td>Blood culture x 2 – Bacteraemia and guide antibiotics</td><td><strong>Urine (SPC)</strong> – Identify UTI and guide antibiotics</td></tr><tr><td><strong>BSL</strong> – Rule out hypoglycaemia given persistent vomiting</td><td>Lumbar puncture – Rule out meningitis</td></tr><tr><td>Abdominal XR – Identify midgut volvulus/intussusception</td><td>Abdominal USS – Identify midgut volvulus/incarcerated hernia/intussusception</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 68 year old woman has presented to your tertiary ED with 3 hours of chest pain.\nHer ECG is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the ECG. (5 marks)\nHer vital signs are:\n\nGCS\n\nBP\n70/40 mmHg\n\nRR\n/min O2 sats 98% room air Temperature 36.5 degrees Celsius"},{"id":"p2","label":"Part 2","prompt":"State 6 components of your management. (6 marks)"}],"propPages":["asset:img2a2a31fa4cc5717c1d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Underlying atrial flutter (1 mark)</div><div class=\"answer-line\"><em><strong>Must get STEMI </strong></em></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">IV fluid load – 500mL NS – pre-load for inferior /RV infarction</div><div class=\"answer-line\"><strong>Aspirin 300mg </strong></div><div class=\"answer-line\">ticagrelor 180mg</div><div class=\"answer-line\">heparin bolus and infusion</div><div class=\"answer-line\"><strong>activate cath lab</strong></div><div class=\"answer-line\">analgesia – IV morphine 2.5mg aliquots until comfortable</div><div class=\"answer-line\">inotropes OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You are planning to conduct a research project in your ED and are currently working out an appropriate design for your study.","parts":[{"id":"p1","label":"Part 1","prompt":"List and describe 4 different types of control groups. (4 marks)"},{"id":"p2","label":"Part 2","prompt":"Complete the following table by providing 2 strengths and 2 limitations of a retrospective study design. (4 marks)"},{"id":"p3","label":"Part 3","prompt":"Complete the following table regarding cohort studies. (4 marks) Type of Cohort study"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"3\">classification of variables</td></tr><tr><td colspan=\"3\">by prospective trials</td></tr><tr><td>Useful for generating</td><td>Difficult to establish cause and</td><td></td></tr><tr><td>hypotheses</td><td>effect relationship</td><td></td></tr><tr><td colspan=\"3\">Selection bias – Only patients</td></tr><tr><td colspan=\"3\">found to have index condition</td></tr><tr><td colspan=\"3\">are included</td></tr><tr><td colspan=\"3\">Data dredging is common</td></tr><tr><td colspan=\"3\">3.</td></tr><tr><td>Type of Cohort study</td><td>Definition</td><td>Key statistic</td></tr><tr><td>Observational study</td><td>Observation of group of</td><td>Relative risk</td></tr><tr><td colspan=\"3\">subjects with risk factor and a</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Odds ratio</div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">and group without</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 39 year old woman has presented with fevers, shortness of breath and productive cough for several days after suffering confirmed Influenza 2 weeks prior. Her chest x-ray is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the chest x-ray. (3 marks)"},{"id":"p2","label":"Part 2","prompt":"List 3 potential bacterial pathogens that might be causing this clinical picture. For each, provide your first choice antibiotic for treatment. (3 marks) The patient’s vital signs are:\n\nGCS\n\nHR\n120 /min\n\nBP\n80/40 mmHg\n\nRR\n/min O2 sats 86% 15L/min O2 via non-rebreather mask\nTemperature 38.5\ndegrees Celsius She is moderately agitated and attempting to push off her oxygen mask. You have decided that she will need to be intubated for ongoing management."},{"id":"p3","label":"Part 3","prompt":"State 5 components of your management (apart from antibiotics) prior to rapid sequence\ninduction of anaesthesia for intubation. Provide justification for each. (5 marks)"}],"propPages":["asset:imgdbc9daf3848c43d140"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Multifocal consolidation in right upper lobe, right middle lobe and left lingula/upper lobe consistent</div><div class=\"answer-line\">with multifocal pneumonia.</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Streptococcus pneumoniae - ceftriaxone</td><td>Staphylococcus aureus – flucloxacillin / vancomycin</td></tr><tr><td>Mycoplasma pneumonia - azithromycin</td><td>+ others</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Ketamine 20mg bolus IV (or similar alternative) to allow pre-oxygenation – <strong>something to control </strong></td><td><strong>IV N/saline bolus – 1L</strong> aim for systolic &gt;100mmHg</td></tr><tr><td>Noradrenaline infusion</td><td>CPAP 10-15cmH20, 100% O2</td></tr><tr><td>Upright positioning</td><td><em>With justification for each </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 34 year old woman has presented with a sudden onset, severe headache and vomiting.\nA slice from her non-contrast CT head is provided below.","parts":[{"id":"p1","label":"Part 1","prompt":"Interpret the CT scan. (3 marks)\nHer vital signs are:\n\nGCS\nE4 V4 M6 Pulse 100 /min\n\nBP\n190/110 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"p2","label":"Part 2","prompt":"State 5 components of your initial management. (5 marks)"},{"id":"p3","label":"Part 3","prompt":"List 4 potential complications of this pathology that might occur in the ED. (4 marks)"}],"propPages":["asset:img810d701d8c36898f30"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\"><strong>Subarachnoid haemorrhage</strong> with dilated temporal horns concerning for obstructive hydrocephalus</div><div class=\"answer-line\">Blood in basal cisterns</div></section><section class=\"answer-part\"><h5>Part 2</h5><div class=\"answer-line\">Analgesia – Fentanyl/morphine with dosing</div><div class=\"answer-line\">Head up 30 degrees</div><div class=\"answer-line\">Bolus hydralazine 5-10mg IV q15min target SBP &lt;140mmHg for unsecured aneurysm</div><div class=\"answer-line\">Nimodipine 60mg via NG q4h</div><div class=\"answer-line\">Ensure normal serum sodium 135-145mmol/L</div><div class=\"answer-line\">Keppra 2g IV load then 500mg BD NG</div><div class=\"answer-line\"><strong>Neurosurgical consultation for aneurysm securement / drain hydrocephalus </strong></div></section><section class=\"answer-part\"><h5>Part 3</h5><div class=\"answer-line\">Seizure - Seizing</div><div class=\"answer-line\">Rebleed – Reduced GCS, blown pupil</div><div class=\"answer-line\">Hydrocephalus –reduced GCS</div><div class=\"answer-line\">Hypertensive crisis – SBP &gt;200mmHg</div><div class=\"answer-line\">Neurogenic APO – Increasing O2 requirement, increased WOB</div><div class=\"answer-line\">Ventricular dysrhythmias – VT on monitor</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"You are working as the morning short stay consultant in your department. You are about to review a 54 year old man who was admitted overnight with alcohol intoxication and suicidal ideation. He was managed with parenteral sedation overnight and has become increasingly agitated after waking up this morning. He has presented many times to the ED with problems related to heavy alcohol use.","parts":[{"id":"p1","label":"Part 1","prompt":"List 6 potential causes for his agitation. Provide a key feature of your history or\nexamination that would support each cause. (12 marks) Cause of agitation Supportive feature of history or examination"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part 1</h5><div class=\"answer-line\">Ongoing alcohol intoxication – Slurred speech, ataxia</div><div class=\"answer-line\">Mental health disorder – features of such eg psychosis</div><div class=\"answer-line\">Unidentified head injury eg subdural – Focal neurology</div><div class=\"answer-line\"><strong>Actively withdrawing</strong> - Tremor</div><div class=\"answer-line\">Delirium tremens – Autonomic dysfunction</div><div class=\"answer-line\">Wernicke encephalopathy – Ataxia, ophthalmoplegia, nystagmus</div><div class=\"answer-line\">Korsakoff psychosis – Confabulation</div><div class=\"answer-line\">Pancreatitis – Tender epigastrium</div><div class=\"answer-line\">Hypoglycaemia – Hx diabetes / signs fulminant liver failure</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
